<?php defined('BASEPATH') or exit('No direct script access allowed');$company_page_title='Recorrência de faturas';require APPPATH.'views/admin/companies/layout_head.php';$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=fn($q='')=>CompanyRequestScope::adminUrl($this,'company_recurring'.$q);$hidden=function($action)use($esc,$company_recurring_csrf){echo '<input type="hidden" name="action" value="'.$esc($action).'"><input type="hidden" name="company_recurring_csrf" value="'.$esc($company_recurring_csrf).'"><input type="hidden" name="request_key" value="'.bin2hex(random_bytes(32)).'">';};$states=['active'=>'Ativa','paused'=>'Pausada','processing'=>'Ocorrência em processamento','completed'=>'Concluída']; ?>
<section class="company-settings-card"><h1>Recorrência de faturas</h1><p>Séries privadas de 1 a 120 emissões, com intervalo de 1 a 12 meses. A origem, destinatário, moeda, configuração e responsável são conferidos em cada emissão. Alterações exigem revisão e nova série.</p><p>Entrega escolhida: notificação manual após emissão. O agendamento não envia mensagens, não cria boleto e não debita clientes. O vencimento mantém o intervalo em dias da primeira fatura.</p>
<?php if($error){?><p role="alert" class="alert alert-danger"><?= $esc($error); ?></p><p><a href="<?= $esc($url()); ?>">Reabrir lista</a></p><?php } ?>
<?php if($detail){?><h2>Série <?= (int)$detail['id']; ?></h2><p><?= $esc($states[$detail['state']]??$detail['state']); ?> · Próxima emissão <?= $esc($detail['next_date']); ?> · <?= (int)$detail['completed_runs']; ?> de <?= (int)$detail['max_runs']; ?></p><p>Origem <?= $esc($detail['context']['identity']['legal_name']); ?> · Cliente <?= $esc($detail['context']['recipient']['name']); ?> · <?= $esc($detail['context']['currency']['name']); ?></p>
<?php if($can_manage&&in_array($detail['state'],['active','processing'],true)&&(int)$detail['actor_id']===$actor){?><?= form_open($url());$hidden('run'); ?><input type="hidden" name="schedule_id" value="<?= (int)$detail['id']; ?>"><button type="submit"><?= $detail['state']==='processing'?'Retomar ocorrência':'Emitir próxima ocorrência vencida'; ?></button><?= form_close(); ?><?php } ?>
<?php if($can_manage&&in_array($detail['state'],['active','paused'],true)){?><?= form_open($url());$hidden($detail['state']==='active'?'pause':'resume'); ?><input type="hidden" name="schedule_id" value="<?= (int)$detail['id']; ?>"><button type="submit"><?= $detail['state']==='active'?'Pausar novas emissões':'Retomar série com a origem original'; ?></button><?= form_close(); ?><?php } ?>
<?php if($detail['last_error']!==''){?><p role="status"><?= $esc(match($detail['last_error']){'origin_changed'=>'Emissão bloqueada por mudança na origem. Preserve esta série e agende outra após revisar os dados.','actor_revoked'=>'Emissão bloqueada: o responsável perdeu acesso. Restaure a autorização legítima ou crie nova série com responsável autorizado.',default=>'A última operação não foi confirmada. Reabra e retome a ocorrência com a mesma origem.'}); ?></p><?php } ?><h3>Ocorrências preservadas</h3><table class="table"><thead><tr><th>Data programada</th><th>Estado</th><th>Fatura</th></tr></thead><tbody><?php foreach($detail['occurrences'] as $run){?><tr><td><?= $esc($run['run_date']); ?></td><td><?= $run['state']==='completed'?'Concluída':'Em processamento'; ?></td><td><?php if((int)$run['invoice_id']>0){?><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_invoices?invoice='.(int)$run['invoice_id'])); ?>">Abrir fatura</a><?php } ?></td></tr><?php } ?></tbody></table><p><a href="<?= $esc($url()); ?>">Voltar à lista</a></p><?php } ?>
<h2>Séries desta empresa</h2><table class="table"><thead><tr><th>Série</th><th>Próxima emissão</th><th>Progresso</th><th>Estado</th></tr></thead><tbody><?php foreach($directory as $row){?><tr><td><a href="<?= $esc($url('?schedule='.(int)$row['id'])); ?>"><?= (int)$row['id']; ?></a></td><td><?= $esc($row['next_date']); ?></td><td><?= (int)$row['completed_runs']; ?>/<?= (int)$row['max_runs']; ?></td><td><?= $esc($states[$row['state']]??$row['state']); ?></td></tr><?php } ?></tbody></table>
<?php if($can_manage){?><h2>Agendar nova série</h2><?= form_open($url());$hidden('create');$recurring_form=true;require APPPATH.'views/admin/companies/sales_form_fields.php'; ?><label for="recurring-months">Intervalo em meses</label><input class="form-control" id="recurring-months" name="interval_months" type="number" min="1" max="12" value="1" required><label for="recurring-max">Número de emissões</label><input class="form-control" id="recurring-max" name="max_runs" type="number" min="1" max="120" value="12" required><button type="submit">Agendar com a origem atual</button><?= form_close(); ?><?php } ?></section>
